def benchmark_pattern(fn, args, num_runs=100):
    # Warmup
    for _ in range(10):
        fn(*args)

    # Benchmark
    start = time.perf_counter()
    for _ in range(num_runs):
        fn(*args)
        torch.cuda.synchronize()
    end = time.perf_counter()

    return (end - start) / num_runs

